\label{thm:classification} Up to the action by the modular group,
there are three thresholds $0<\alpha_a<\alpha_b<\alpha_c<1$ such that
\begin{equation}\aligned\nonumber
\operatorname*{minima}_{z\in\mathbb H,\,(a,b)\in\mathbb R^2}\Big(\theta(1;z)+\alpha J(z;a,b)\Big)=
\begin{cases}
\;\big(e^{i{\pi}/{3}};1/3,1/3\big), &\hbox{if}\;\; \alpha\in[0,\alpha_a),\\
\;\big(e^{i{\pi}/{3}};1/3,1/3\big)\;\hbox{or}\;\big(e^{i{\varphi_{\alpha_a}}};1/2,1/2\big), &\hbox{if}\;\; \alpha=\alpha_a,\\
\;\big(e^{i{\varphi_\alpha}};1/2,1/2\big),\;\varphi_\alpha\in(\varphi_{\alpha_a},\frac{\pi}{2}),\;\; &\hbox{if}\;\; \alpha\in(\alpha_a,\alpha_b),\\
\;\big(i;1/2,1/2\big),\; &\hbox{if}\;\; \alpha\in[\alpha_b,\alpha_c],\\
\;\big(iy_\alpha;1/2,1/2\big),\; y_\alpha\in(1,\sqrt3],\;\;y_1=\sqrt3,\;\;&\hbox{if}\;\; \alpha\in(\alpha_c,1],
\end{cases}
\endaligned\end{equation}
More precisely, all minimizing configurations are classified as follows:
\begin{enumerate}
\item If $\alpha\in(0,\alpha_a)$, the lattice is triangular and
      $(a,b)=(1/3,1/3)$.
\item If $\alpha=\alpha_a$, the transition
changes both the displacement and the lattice shape discontinuously. It admits two different type minimizers. They are triangular lattice with $(a,b)=(1/3,1/3)$
       and the centered rhombic configuration
      $(e^{i\varphi_{\alpha_a}};1/2,1/2)$.
\item If $\alpha\in(\alpha_a,\alpha_b)$, the vortex is rhombic changing with $\alpha$ and the relative position is $(a,b)=(1/2,1/2)$ keeping fixed.

\item If $\alpha\in[\alpha_b,\alpha_c]$, the vortex is square and the relative position is $(a,b)=(1/2,1/2)$, both are unchanged with the parameter.

\item If $\alpha\in(\alpha_c,1]$, the vortex is rectangular changing with the parameter $\alpha$ and the relative position is $(a,b)=(1/2,1/2)$. Furthermore $y_\alpha\in(1,\sqrt3]$ and $y_1=\sqrt3$.
\end{enumerate}

Here $\alpha_b$ and $\alpha_c$ are given by
\begin{equation}\label{eq:centered-thresholds}
 \alpha_b=-\frac{\theta_{xx}(1;i)}
                   {J_{xx}(i;1/2,1/2)},\qquad
 \alpha_c=-\frac{\theta_{yy}(1;i)}
                   {J_{yy}(i;1/2,1/2)}.
\end{equation}
The pair $(\alpha_a,\varphi_{\alpha_a})$ is determined uniquely by the minimization identity:
\[
\begin{aligned}
E_{\alpha}(e^{i\pi/3};1/3,1/3)
 =\min_{\varphi\in[\pi/3,\pi/2]}E_{\alpha}(e^{i\varphi};1/2,1/2),\;\;\alpha\in(0,3/{10}).
\end{aligned}
\]
$\varphi_\alpha\in(\pi/3,\pi/2)$
is the unique solution of
\begin{equation}\label{eq:rhombic-branch}
 \frac{d}{d\varphi}E_\alpha(e^{i\varphi};1/2,1/2)=0
 \;\;\hbox{for}\;\;\alpha\in(0,\alpha_b).
\end{equation}
$y_\alpha\in(1,\sqrt3]$ is
the unique solution of
\begin{equation}\label{eq:rectangular-branch}
  \frac{d}{d y}E_\alpha(iy;1/2,1/2)=0,\;\;\hbox{for}\;\;\alpha\in(\alpha_b,1).
\end{equation}

Numerically,
\begin{equation}\nonumber
\begin{aligned}
 \alpha_a=&0.172356\cdots,\;
 \alpha_b=0.373215\cdots,\;
 \alpha_c=0.925649\cdots,\;
 \varphi_{\alpha_a}=1.185955\cdots.
\end{aligned}
\end{equation}

\label{Def}
The fundamental domain associated to group $G$ is a connected domain $\mathcal{D}$ that satisfies:
\begin{itemize}
  \item [(1)] For any $z\in\mathbb{H}$, there exists an element $\pi\in G$ such that $\pi(z)\in\overline{\mathcal{D}}$;
  \item [(2)] Suppose $z_1,z_2\in\mathcal{D}$ and $\pi(z_1)=z_2$ for some $\pi\in G$, then $z_1=z_2$ and $\pi=\pm Id$.
\end{itemize}

\label{Prop21}
Let $\alpha\in{\mathbb R}$, $z\in\mathbb H$, and
$(a,b)\in\mathbb R^2$. Then
\begin{equation}\label{Eq21}
\begin{aligned}
 &E_\alpha(z+1;a-b,b)=E_\alpha(z;a,b),\\
 &E_\alpha(-1/z;-b,a)=E_\alpha(z;a,b),\\
 &E_\alpha(-\bar z;a,-b)=E_\alpha(z;a,b).
\end{aligned}
\end{equation}
and
\begin{equation}\label{Eq22}\begin{aligned}
 &E_\alpha(z;a+1,b)=E_\alpha(z;a,b),\\
  &E_\alpha(z;a,b+1)=E_\alpha(z;a,b),\\
  &E_\alpha(z;1-a,1-b)=E_\alpha(z;a,b)
\end{aligned}\end{equation}

Whenever a minimum is attained,
\begin{equation*}\begin{aligned}
\min_{z\in\mathbb{H}, (a,b)\in\mathbb{R}^2} E_\alpha(z;a,b)
=\min_{z\in\overline{\mathcal{D}_{\mathcal{G}}}, (a,b)\in\mathbb{R}^2} E_\alpha(z;a,b)
=\min_{z\in\overline{\mathcal{D}_{\mathcal{G}}}, (a,b)\in[0,1]^2} E_\alpha(z;a,b).
\end{aligned}\end{equation*}

\label{lem:analytic-properties}

\begin{equation}\label{eq:positive-translated}
 J(z;a,b)=\sum_{p,q\in\mathbb Z}
 \exp\!\left[-\pi\left(
 \frac{(p+a+x(q+b))^2}{y}+y(q+b)^2\right)\right],
\end{equation}
and
\begin{equation}\label{eq:translated-bounds}
 0<J(z;a,b)\leq\theta(1;z).
\end{equation}
Equality in the upper bound holds if and only if
$(a,b)\in\mathbb Z^2$.

\label{lem:centered-identity}
For $z\in\mathbb H$ and $\alpha\in{\mathbb R}$,
\begin{equation}\label{eq:centered-identity}
 E_\alpha(z;1/2,1/2)
 =(1-\alpha)\theta(1;z)+2\alpha\theta\big(2;\frac{z+1}{2}\big).
\end{equation}

\label{lem:four}
Let $0\leq\alpha\leq1$ and $z=x+iy\in\mathbb H$.
For $(m,n)\in\mathbb Z^2$, define
\begin{equation}\label{eq:lattice-quadratic-form}
 Q_{m,n}=Q_{m,n}(x,y):=\frac{|mz-n|^2}{y}
                       =m^2y+\frac{(mx-n)^2}{y},
\end{equation}
and put
\[
 A=e^{-\pi(y+x^2/y)},\quad B=e^{-\pi/y},\quad
 C=e^{-\pi(y+(x-1)^2/y)},\quad D=e^{-\pi(y+(x+1)^2/y)}.
\]
Assume that
\[
 x\geq0,\qquad A^2>4CD,\qquad B^2>4CD.
\]
Then, for every $(a,b)\in\mathbb R^2$,
\begin{align}\label{eq:lower}
 E_\alpha(z;a,b)\geq{}&1+\alpha+2(A+B+C+D)\\
 &+2\alpha\min_{-1\leq t\leq1}
 \left[Bt-\sqrt{A^2+(C-D)^2+2A(C+D)t+4CDt^2}\right]\nonumber\\
 &+(1-\alpha)
 \sum_{\substack{|m|,|n|\leq2\\
 (m,n)\notin\{(0,0),\pm(1,0),\pm(0,1),\pm(1,1),\pm(1,-1)\}}}
 e^{-\pi Q_{m,n}}.\nonumber
\end{align}
The right-hand side is locally Lipschitz in $(x,y)$, and the scalar
minimum is attained uniquely at
\[
\begin{aligned}
 t&=\max\{-1,\min\{1,t_0\}\},\\
 t_0&=
 \frac{A^2(C+D)^2-B^2[A^2+(C-D)^2]}
 {\sqrt{B^2-4CD}
 [B(C-D)\sqrt{A^2-4CD}+A(C+D)\sqrt{B^2-4CD}]}.
\end{aligned}
\]

\label{lem:hex-convexity}
For $4/25\le\alpha\le7/40$, the Hessian of $E_\alpha$ in the
real variables $(x,y,a,b)$ is positive definite on the affine prism
\begin{equation}\label{eq:hex-affine-prism}
\begin{gathered}
 \frac{19}{40}\le x\le\frac12,\qquad \frac{\sqrt3}{2}\le y\le \frac{\sqrt3}{2}+\frac1{40},\\
 a=\frac13-\left(x-\frac12\right)-\frac{29}{50}\left(y-\frac{\sqrt3}{2}\right)+r_a,
 \qquad b=\frac13+\frac{29}{25}\left(y-\frac{\sqrt3}{2}\right)+r_b,\\
 |r_a|\le\frac3{400},\qquad |r_b|\le\frac3{500}.
\end{gathered}
\end{equation}
